import {readFileSync,existsSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
import {parse} from 'yaml';
import {SourceTextModule} from 'node:vm';
const root='skills/load-testing-advanced';
const docs=['SKILL.md','references/generator-configuration.md','references/test-profiles.md'];
let links=0;
for(const relative of docs){const file=resolve(root,relative);const text=readFileSync(file,'utf8');for(const m of text.matchAll(/\[[^\]]*\]\((?:<([^>]+)>|([^\s)]+))\)/g)){const target=m[1]||m[2];if(/^https?:/.test(target))continue;const [local,anchor]=target.split('#');const dest=local?resolve(dirname(file),local):file;if(!existsSync(dest))throw new Error('Missing link: '+target);if(anchor){const headings=Array.from(readFileSync(dest,'utf8').matchAll(/^#+\s+(.+)$/gm),h=>h[1].toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s/g,'-'));if(!headings.includes(anchor))throw new Error('Missing anchor: '+target);}links++;}}
const body=readFileSync(root+'/SKILL.md','utf8');const front=parse(body.split('---')[1]);const manifest=parse(readFileSync(root+'/skill.yaml','utf8'));
if(front.description.trim()!==manifest.description.trim())throw new Error('Description mismatch');
for(const name of manifest.suggests)if(!existsSync('skills/'+name+'/SKILL.md'))throw new Error('Missing suggest '+name);
const snippet=readFileSync(root+'/references/generator-configuration.md','utf8').match(/```javascript\r?\n([\s\S]*?)```/)[1];new SourceTextModule(snippet);
console.log(JSON.stringify({relativeLinks:links,descriptionsMatch:true,suggestsExist:manifest.suggests.length,partialJavaScriptOptionsSyntax:'PASS (Node parser only, not k6 execution)',version:manifest.version}));
